// The `nook` module: what a mod may ask of openNook and the machine. Generated by openNook;
// do not edit.
//
// Live reads (media, agents, apps, island, shared, theme, props) are tracked: when what a
// mod read changes, the mod renders again. No subscribing.

export interface Media {
  title: string | null;
  artist: string | null;
  album: string | null;
  /** Seconds. */
  duration: number | null;
  /** Seconds, as of `sampledAt`. Now: elapsed + (Date.now() - sampledAt) / 1000 while
   *  playing. Moves only on a seek, pause or new track, so tick the position yourself. */
  elapsed: number | null;
  /** Milliseconds since the epoch; 0 while paused. */
  sampledAt: number;
  playing: boolean;
  /** "Spotify", "Music", "Safari", … */
  app: string | null;
  bundleId: string | null;
  /** An image source for image() ("nook:art/…"). */
  artwork: string | null;
  /** Three colours from the artwork ("#rrggbb"), most prominent first; null without artwork. */
  colors: [string, string, string] | null;
  shuffle: boolean | null;
  repeat: "off" | "one" | "all" | null;
}

export interface Agent {
  /** "Claude", "Codex", "OpenCode", "Cursor", "Gemini", "Grok", "Aider", "Pi", "Fx". */
  kind: string;
  pid: number;
  /** The session's name, else its project folder's. */
  title: string;
  project: string;
  cwd: string;
  status: "working" | "waiting";
  sessionId: string | null;
  model: string | null;
  /** A built-in icon for this agent's logo, for icon(). */
  icon: string;
}

export interface App {
  bundleId: string;
  name: string;
  pid: number;
}

export interface Island {
  expanded: boolean;
  /** The mod whose page shows when open. */
  selected: string | null;
  /** The mod that owns the closed island now. */
  active: string | null;
  notch: { width: number; height: number; hasNotch: boolean };
  /** Content width of the open island's page, in points. */
  page: { width: number };
  screen: { width: number; height: number };
}

export interface Location {
  latitude: number;
  longitude: number;
  /** The place's name (reverse geocoded, or as set in Settings), when known. */
  name: string | null;
  /** Its time zone ("Europe/Berlin"), when known. */
  timezone: string | null;
  /** True when it's the Mac's own location (so the Mac's clock is its time). */
  live?: boolean;
}

export function media(): Media | null;
/** Where the person is: the place they set in Settings › General › Location, else the Mac's
 *  location (reduced accuracy). null until it's found, `{ error }` when it can't be. The
 *  first read of the Mac's location asks the person for permission. */
export function location(): Location | { error: string } | null;
export function agents(): Agent[];
export function apps(): App[];
export function appRunning(bundleId: string): boolean;
export function island(): Island;

export function shared(key: string): unknown;
export function setShared(key: string, value: unknown): void;

export function props(): Record<string, unknown>;
export function home(): string;
/** `~/.config/opennook`. */
export function appHome(): string;
/** This mod's folder. */
export function modDir(): string;
/** "macos", "linux" or "windows". */
export function platform(): string;
/** Theme colors by token. */
export function theme(): Record<string, string>;

/**
 * Runs an openNook command (fire and forget):
 * - island.expand, island.collapse, island.toggle, island.select {mod}, island.peek {mod?, ms?}
 * - media.toggle, media.play, media.pause, media.next, media.previous, media.seek {seconds},
 *   media.shuffle, media.repeat
 * - agents.focus {pid}, agents.reveal {cwd}
 * - open {target}: a URL, file or folder
 */
export function run(command: string, args?: Record<string, unknown>): void;
export function open(target: string): void;

export interface ExecResult {
  code: number;
  stdout: string;
  stderr: string;
}
/** Runs a program with the user's PATH (Homebrew, ~/.local/bin, …). 30 s limit, 8 MiB output.
 *  Rejects when it can't start or runs too long. */
export function exec(command: string, args?: string[], options?: { cwd?: string }): Promise<ExecResult>;
/** UTF-8 text (up to 4 MiB), or null when absent. `~/` is home; relative is the mod's folder. */
export function readTextFile(path: string): Promise<string | null>;
/** Replaces a file atomically. Only under appHome(). */
export function writeTextFile(path: string, text: string): Promise<null>;
/** Calls `onLine` for each line appended to a file from now on (or the last `fromEnd` lines
 *  first). Survives rotation. Returns a function that stops following. */
export function tail(path: string, onLine: (line: string, cx: import("nook/ui").Cx) => void, options?: { fromEnd?: number }): () => void;
/** Calls `onChange` with the file's text (null when absent) now and on every change. */
export function watchFile(path: string, onChange: (text: string | null, cx: import("nook/ui").Cx) => void): () => void;

// Globals: fetch(url, { method, headers, body }) -> { status, ok, headers, text(), json() },
// localStorage (per mod), console.log/warn/error (to logs/<mod>.log).
